using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using MonoTorrent;

namespace WinIDM.Torrent.Tests.Support;

/// <summary>One file in the source content, with its reference SHA-256.</summary>
internal sealed record SourceFile(string RelativePath, long Length, string Sha256);

/// <summary>
/// Random content and a .torrent generated by MonoTorrent <c>TorrentCreator</c>.
/// The content lives in <c>{ContentRoot}\{Name}</c>; the correct download lives in <c>{SaveDirectory}\{Name}</c>
/// with <c>SaveDirectory = ContentRoot</c> for the seeder.
/// </summary>
internal sealed class SourceTorrent
{
    public required string Name { get; init; }
    public required string ContentRoot { get; init; }
    public required string TorrentPath { get; init; }
    public required string InfoHash { get; init; }
    public required int PieceLength { get; init; }
    public required IReadOnlyList<SourceFile> Files { get; init; }
    public long TotalLength => Files.Sum(f => f.Length);

    /// <summary>Source file path for a given relative file.</summary>
    public string SourcePathOf(SourceFile file) =>
        Path.Combine(ContentRoot, Name, file.RelativePath.Replace('/', Path.DirectorySeparatorChar));

    /// <summary>Download file path under the given save folder.</summary>
    public string DownloadPathOf(string saveDirectory, SourceFile file) =>
        Path.Combine(saveDirectory, Name, file.RelativePath.Replace('/', Path.DirectorySeparatorChar));
}

/// <summary>Integration utilities: random content, .torrent generation, free ports, and conditional waiters.</summary>
internal static class IntegrationKit
{
    public const int DefaultPieceLength = 64 * 1024;

    /// <summary>
    /// Generate random content (<paramref name="files"/> = relative path, byte size) and a MonoTorrent .torrent
    /// pointing at <paramref name="announceUrl"/>. No network is accessed.
    /// </summary>
    public static async Task<SourceTorrent> CreateSourceTorrentAsync(
        string rootDirectory,
        string name,
        IReadOnlyList<(string RelativePath, int Size)> files,
        string announceUrl,
        int pieceLength = DefaultPieceLength)
    {
        var contentRoot = Path.Combine(rootDirectory, "src");
        var folder = Path.Combine(contentRoot, name);
        Directory.CreateDirectory(folder);

        var sourceFiles = new List<SourceFile>();
        foreach (var (relative, size) in files)
        {
            var path = Path.Combine(folder, relative.Replace('/', Path.DirectorySeparatorChar));
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            var content = RandomNumberGenerator.GetBytes(size);
            await File.WriteAllBytesAsync(path, content).ConfigureAwait(false);
            sourceFiles.Add(new SourceFile(relative, size, Sha256Hex(content)));
        }

        var torrentPath = Path.Combine(rootDirectory, name + ".torrent");
        var creator = new TorrentCreator(TorrentType.V1Only)
        {
            PieceLength = pieceLength,
            Announce = announceUrl,
            CreatedBy = "WinIDM integration test",
            Comment = null,
        };
        var source = new TorrentFileSource(folder) { TorrentName = name };
        await creator.CreateAsync(source, torrentPath).ConfigureAwait(false);

        var parsed = await MonoTorrent.Torrent.LoadAsync(torrentPath).ConfigureAwait(false);

        // TorrentCreator sorts files alphabetically: the Files index must match the order inside the torrent.
        var ordered = parsed.Files
            .Select(tf => sourceFiles.Single(s => NormalizePath(s.RelativePath) == NormalizePath(tf.Path)))
            .ToList();

        return new SourceTorrent
        {
            Name = name,
            ContentRoot = contentRoot,
            TorrentPath = torrentPath,
            InfoHash = parsed.InfoHashes.V1OrV2.ToHex().ToLowerInvariant(),
            PieceLength = pieceLength,
            Files = ordered,
        };
    }

    private static string NormalizePath(string path) => path.Replace('\\', '/');

    public static string Sha256Hex(byte[] data) => Convert.ToHexString(SHA256.HashData(data)).ToLowerInvariant();

    public static async Task<string> Sha256FileAsync(string path)
    {
        await using var fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete);
        var hash = await SHA256.HashDataAsync(fs).ConfigureAwait(false);
        return Convert.ToHexString(hash).ToLowerInvariant();
    }

    /// <summary>Reserve free loopback TCP ports. All ports are held at once first so they cannot be the same.</summary>
    public static int[] ReserveFreePorts(int count)
    {
        var listeners = new List<TcpListener>(count);
        try
        {
            for (var i = 0; i < count; i++)
            {
                var listener = new TcpListener(IPAddress.Loopback, 0);
                listener.Start();
                listeners.Add(listener);
            }
            return listeners.Select(l => ((IPEndPoint)l.LocalEndpoint).Port).ToArray();
        }
        finally
        {
            foreach (var listener in listeners) listener.Stop();
        }
    }

    /// <summary>Wait until the condition is true. A timeout throws <see cref="TimeoutException"/> with the description.</summary>
    public static async Task WaitUntilAsync(Func<bool> condition, string description, TimeSpan? timeout = null)
    {
        var deadline = DateTime.UtcNow + (timeout ?? TimeSpan.FromSeconds(60));
        while (DateTime.UtcNow < deadline)
        {
            if (condition()) return;
            await Task.Delay(50).ConfigureAwait(false);
        }
        if (condition()) return;
        throw new TimeoutException("Timed out waiting: " + description);
    }
}
